var MAP={"MT-STAT2": ["Statistiques à deux variables / ajustement", "Exploitation de mesures de charge, contrôle de performance et analyse de données d’un équipement électrique."], "MT-PROBA": ["Probabilités", "Fiabilité des équipements, détection de défauts et maintenance préventive."], "MT-SUIT-GEO": ["Suites géométriques", "Suivi de consommation énergétique et évolution périodique d’un indicateur électrotechnique."], "MT-POLY3": ["Fonctions polynômes de degré 3 / dérivation et variations", "Analyse et optimisation d’une grandeur électrotechnique : puissance, rendement, charge ou réglage."], "MT-EXPLOG": ["Fonctions exponentielles et logarithme décimal", "Modélisation d’une évolution : consommation, vieillissement, charge ou performance d’un système."], "MT-TRIG": ["Trigonométrie", "Étude des signaux sinusoïdaux : fréquence, période, déphasage et représentation de Fresnel."], "MT-ALGO": ["Algorithmique et programmation", "Automatisation de calculs, exploitation de mesures et traitement numérique de données électrotechniques."], "M1-SUIT-AR": ["Suites arithmétiques", "Planification d’opérations, évolution régulière d’un indicateur ou d’une quantité de production."], "M1-POLY2": ["Fonctions polynômes de degré 2", "Modélisation et analyse d’une grandeur technique dans une situation électrotechnique."], "M1-DERIV": ["Dérivée et variations", "Optimisation et étude de l’évolution d’une grandeur de fonctionnement."], "M1-TRIG": ["Trigonométrie", "Analyse de grandeurs périodiques et préparation à l’étude des signaux électriques."], "M1-VECT": ["Vecteurs du plan", "Représentation vectorielle de grandeurs et préparation aux représentations de Fresnel."], "S1-PUI-DC": ["Puissance et énergie électriques en continu", "Mesure et calcul de puissance/énergie d’un récepteur électrique en régime continu."], "S1-PUI-AC": ["Puissance active et facteur de puissance", "Caractérisation énergétique d’un récepteur en régime sinusoïdal."], "S1-JOULE": ["Effet Joule et pertes", "Pertes électriques, échauffement des conducteurs et efficacité du transport de l’énergie."], "S1-MAG": ["Champ magnétique", "Principe des actionneurs, bobines et phénomènes magnétiques en électrotechnique."], "ST-RED": ["Diode, pont de diodes, redressement et filtrage", "Conversion alternatif-continu et alimentation des équipements électriques."], "ST-MOT": ["Moteurs et bilan de puissance", "Conversion électromécanique, rendement et performances d’un moteur."], "ST-TRI": ["Réseau triphasé", "Distribution triphasée, tensions simples/composées et alimentation des récepteurs."], "ST-IND": ["Induction électromagnétique / loi de Lenz", "Production de tension alternative, transformateurs et machines électriques."], "ST-BAT": ["Piles, accumulateurs et énergie stockée", "Stockage d’énergie, autonomie et alimentation secourue."], "ST-REDOX": ["Oxydoréduction", "Phénomènes électrochimiques liés aux matériaux et aux installations électriques."], "ST-CORR": ["Corrosion, passivation et anode sacrificielle", "Protection des masses métalliques, durabilité des équipements et maintenance."], "ST-SIGNAL": ["Transmission de l’information / ondes", "Transmission de données et communication dans les systèmes connectés."], "ST-ACOU": ["Acoustique", "Mesures de niveau sonore et prévention des risques en environnement industriel."], "M-PRE-FRAC": ["Prérequis — calcul fractionnaire", "Calculs de rapports, rendements, proportions et transformation de formules électriques."], "M-PRE-EQ1": ["Prérequis — équations du premier degré", "Isolement d’une grandeur dans les relations électriques et physiques."], "M-PRE-FORM": ["Prérequis — transformation de formules", "Isolement et calcul de grandeurs électriques : U, I, R, P, E, etc."]};
