function cat(a){var n=a.reduce(function(s,x){return s+x.length},0),u=new Uint8Array(n),o=0;a.forEach(function(x){u.set(x,o);o+=x.length});return u}
function bytes(s){return new TextEncoder().encode(s)} function dos(){var d=new Date();return [((d.getHours()&31)<<11)|((d.getMinutes()&63)<<5)|(Math.floor(d.getSeconds()/2)&31),(((d.getFullYear()-1980)&127)<<9)|(((d.getMonth()+1)&15)<<5)|(d.getDate()&31)]}
function zip(files){var L=[],C=[],off=0,dt=dos();Object.keys(files).forEach(function(n){var data=files[n],nb=bytes(n),cr=crc(data),l=cat([u32(0x04034b50),u16(20),u16(0),u16(0),u16(dt[0]),u16(dt[1]),u32(cr),u32(data.length),u32(data.length),u16(nb.length),u16(0),nb,data]);L.push(l);C.push(cat([u32(0x02014b50),u16(20),u16(20),u16(0),u16(0),u16(dt[0]),u16(dt[1]),u32(cr),u32(data.length),u32(data.length),u16(nb.length),u16(0),u16(0),u16(0),u16(0),u32(0),u32(off),nb]));off+=l.length});var cd=cat(C),bd=cat(L);return cat([bd,cd,cat([u32(0x06054b50),u16(0),u16(0),u16(C.length),u16(C.length),u32(cd.length),u32(bd.length),u16(0)])])}
function uniq(a){var o={},r=[];a.forEach(function(x){if(x&&!o[x]){o[x]=1;r.push(x)}});return r}
function autoData(a){var ks=[];(a.exercises||[]).forEach(function(e){(e.knowledgeIds||[]).forEach(function(k){ks.push(k)})});ks=uniq(ks);var mods=[],pros=[];ks.forEach(function(k){if(MAP[k]){mods.push(MAP[k][0]);pros.push(MAP[k][1])}});mods=uniq(mods);pros=uniq(pros);if(!mods.length)mods=(a.exercises||[]).map(function(e){return e.title}).slice(0,3);var mod=mods.join(' • ');if(mod.length>150)mod=mods.slice(0,2).join(' • ');var pro=pros.join(' ');if(pro.length>230)pro=pros.slice(0,2).join(' ');if(!pro)pro='Application des mathématiques/sciences à l’analyse, au contrôle et à la maintenance d’un système électrotechnique.';return {module:mod,professional:pro}}
function data(a){var m=meta(a),all=load(),d=all[m.code];if(!d){d=autoData(a);all[m.code]=d;save(all)}return d}
