function refresh(force){var a=current();if(!a)return;var d=force?autoData(a):data(a);if(force)setData(a,d);if($('v46Module'))$('v46Module').value=d.module||'';if($('v46Pro'))$('v46Pro').value=d.professional||''}
function nextRels(xml){var max=10,m;var re=/Id="rId(\d+)"/g;while((m=re.exec(xml)))max=Math.max(max,Number(m[1]));return [max+1,max+2]}
async function addCover(blob,a,cor){var u=new Uint8Array(await blob.arrayBuffer()),f=readZip(u),dec=new TextDecoder('utf-8');if(f['word/media/v46-cover-top.png'])return blob;var doc=dec.decode(f['word/document.xml']),rels=dec.decode(f['word/_rels/document.xml.rels']),types=dec.decode(f['[Content_Types].xml']),ids=nextRels(rels),d=data(a),m=meta(a);var title='ÉVALUATION N° '+m.display+(cor?' — CORRIGÉ':'');var module='MODULE'+((d.module||'').indexOf(' • ')>=0?'S':'')+' CONCERNÉ'+((d.module||'').indexOf(' • ')>=0?'S':'')+' : '+(d.module||'À préciser');var pro='LIEN PROFESSIONNEL ÉLECTROTECHNIQUE : '+(d.professional||'À préciser');var level=(a.level==='TMELEC'?'Terminale Bac Pro MELEC':'Première Bac Pro MELEC')+'  •  '+(a.discipline==='sciences'?'Sciences physiques':a.discipline==='mixed'?'Mathématiques & Sciences':'Mathématiques')+'  •  '+a.duration+' min';var cov=COVER.replace(/__RID_TOP__/g,'rId'+ids[0]).replace(/__RID_CERT__/g,'rId'+ids[1]).replace(/__TITLE__/g,escXml(title)).replace(/__MODULE__/g,escXml(module)).replace(/__PRO__/g,escXml(pro)).replace(/__LEVEL__/g,escXml(level));doc=doc.replace('<w:body>','<w:body>'+cov);rels=rels.replace('</Relationships>','<Relationship Id="rId'+ids[0]+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/v46-cover-top.png"/><Relationship Id="rId'+ids[1]+'" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/v46-certifications.png"/></Relationships>');if(!/Extension="png"/.test(types))types=types.replace('<Types ','<Types ').replace('>','><Default Extension="png" ContentType="image/png"/>');f['word/document.xml']=bytes(doc);f['word/_rels/document.xml.rels']=bytes(rels);f['[Content_Types].xml']=bytes(types);f['word/media/v46-cover-top.png']=b64(TOP);f['word/media/v46-certifications.png']=b64(CERT);return new Blob([zip(f)],{type:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'})}
