async function one(cor){var a=current();if(!a){toast('Générez d’abord une évaluation.','warning');return}try{var space=$('v44AnswerSpace')?$('v44AnswerSpace').value:'comfort',r=await V45.latexV1(a,cor,space),b=await addCover(r.blob,a,cor);dlBlob(name(a,cor),b);toast('Word V1 LaTeX + page de garde CFAI créé. Lancez ensuite FINALISER_WORD_LATEX.cmd sur le PC.','success')}catch(e){console.error(e);toast('Erreur V4.6 : '+e.message,'error')}}
async function both(){var a=current();if(!a){toast('Générez d’abord une évaluation.','warning');return}try{var space=$('v44AnswerSpace')?$('v44AnswerSpace').value:'comfort',s=await V45.latexV1(a,false,space),c=await V45.latexV1(a,true,space),bs=await addCover(s.blob,a,false),bc=await addCover(c.blob,a,true),f1=new File([bs],name(a,false),{type:bs.type}),f2=new File([bc],name(a,true),{type:bc.type});if(navigator.canShare&&navigator.share&&navigator.canShare({files:[f1,f2]})){try{await navigator.share({files:[f1,f2],title:'Évaluation CFAI avec page de garde'});return}catch(e){if(e.name==='AbortError')return}}dlBlob(f1.name,bs);setTimeout(function(){dlBlob(f2.name,bc)},350)}catch(e){console.error(e);toast('Erreur V4.6 : '+e.message,'error')}}
function install(){var old=$('v45LatexCfai');if(!old)return false;if($('v46CoverCfai'))return true;old.style.display='none';var div=document.createElement('div');div.id='v46CoverCfai';div.className='v42-note';div.style.marginTop='12px';div.innerHTML='<strong>📘 WORD CFAI — V4.6 PAGE DE GARDE + LATEX</strong><br>La page de garde reprend la couverture du modèle CFAI et indique le numéro d’évaluation, le ou les modules et le lien avec la partie professionnelle électrotechnique.<div style="margin-top:9px"><label style="font-weight:700">Module(s) concerné(s)</label><input id="v46Module" style="width:100%;margin-top:4px;padding:8px;border:1px solid #ccd4e3;border-radius:8px"></div><div style="margin-top:8px"><label style="font-weight:700">Lien professionnel électrotechnique</label><textarea id="v46Pro" rows="3" style="width:100%;margin-top:4px;padding:8px;border:1px solid #ccd4e3;border-radius:8px"></textarea></div><div class="btn-row" style="margin-top:8px"><button class="btn btn-sm btn-outline" id="v46Auto">↻ Déduire automatiquement</button><button class="btn btn-sm btn-primary" id="v46Sujet">📄 Sujet V1 + garde</button><button class="btn btn-sm btn-outline" id="v46Corr">✅ Corrigé V1 + garde</button><button class="btn btn-sm btn-success" id="v46Both">📤 Envoyer les 2</button></div><p class="form-hint">Les deux champs sont proposés automatiquement à partir des notions de l’évaluation, mais restent modifiables avant génération. Sur PC : FINALISER_WORD_LATEX.cmd transforme ensuite toutes les formules en équations Word natives.</p>';old.parentNode.insertBefore(div,old.nextSibling);refresh(false);$('v46Auto').onclick=function(e){e.preventDefault();refresh(true)};function persist(){var a=current();if(a)setData(a,{module:$('v46Module').value.trim(),professional:$('v46Pro').value.trim()})}$('v46Module').addEventListener('change',persist);$('v46Pro').addEventListener('change',persist);$('v46Sujet').onclick=function(e){e.preventDefault();persist();one(false)};$('v46Corr').onclick=function(e){e.preventDefault();persist();one(true)};$('v46Both').onclick=function(e){e.preventDefault();persist();both()};return true}
